insert into questoes (banco, origem_id, categoria, contexto, enunciado, imagem_url, alternativas, correta, explicacao, ativo) values
('logico', 'cc2611-logico-001', 'Problemas lógicos', null, 'Cinco comissários chegaram ao briefing em horários diferentes. Davi chegou primeiro e Eva chegou por último. Carla chegou depois de Davi e antes de Ana. Ana chegou antes de Bruno. Quem chegou em 3º lugar?', null, '[{"letra": "A", "texto": "Carla", "imagem_url": null}, {"letra": "B", "texto": "Bruno", "imagem_url": null}, {"letra": "C", "texto": "Davi", "imagem_url": null}, {"letra": "D", "texto": "Ana", "imagem_url": null}]'::jsonb, 'D', 'Davi é o 1º e Eva a 5ª. Carla vem antes de Ana, e Ana antes de Bruno: Davi, Carla, Ana, Bruno, Eva. Ana é a 3ª.', false),
('logico', 'cc2611-logico-002', 'Problemas lógicos', null, 'Três pilotos, X, Y e Z: um sempre diz a verdade e os outros dois sempre mentem. X diz: "Y mente". Y diz: "Z mente". Z diz: "X e Y mentem". Quem diz a verdade?', null, '[{"letra": "A", "texto": "Não é possível saber", "imagem_url": null}, {"letra": "B", "texto": "X", "imagem_url": null}, {"letra": "C", "texto": "Z", "imagem_url": null}, {"letra": "D", "texto": "Y", "imagem_url": null}]'::jsonb, 'D', 'Se Y fala a verdade, Z mente (então não é verdade que X e Y mentem, o que confere, já que Y é sincero) e X mente ao dizer que Y mente. Só há um sincero: Y. Testando X ou Z como sinceros aparece contradição.', false),
('logico', 'cc2611-logico-003', 'Problemas lógicos', null, 'Um voo parte toda terça-feira. Hoje é quinta-feira, dia 10. Em que dia será o próximo voo?', null, '[{"letra": "A", "texto": "Dia 17", "imagem_url": null}, {"letra": "B", "texto": "Dia 16", "imagem_url": null}, {"letra": "C", "texto": "Dia 15", "imagem_url": null}, {"letra": "D", "texto": "Dia 14", "imagem_url": null}]'::jsonb, 'C', 'Quinta 10, sexta 11, sábado 12, domingo 13, segunda 14, terça 15.', false),
('logico', 'cc2611-logico-004', 'Problemas lógicos', null, 'Em uma tripulação de 12 pessoas, 7 falam inglês, 5 falam espanhol e 2 falam os dois idiomas. Quantas pessoas não falam nenhum dos dois?', null, '[{"letra": "A", "texto": "0", "imagem_url": null}, {"letra": "B", "texto": "1", "imagem_url": null}, {"letra": "C", "texto": "3", "imagem_url": null}, {"letra": "D", "texto": "2", "imagem_url": null}]'::jsonb, 'D', 'Falam pelo menos um idioma: 7 + 5 − 2 = 10. Não falam nenhum: 12 − 10 = 2.', false),
('logico', 'cc2611-logico-005', 'Problemas lógicos', null, 'Quatro passageiros ocupam os assentos A, B, C e D de uma fileira, da esquerda para a direita. A e D são janelas. Lia não está na janela. Rui está imediatamente à direita de Lia. Tom está no assento D. Em qual assento está Bia?', null, '[{"letra": "A", "texto": "D", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'C', 'Lia está em B ou C. Se Lia estivesse em C, Rui ficaria em D, mas D é do Tom. Então Lia está em B, Rui em C e Bia em A.', false),
('logico', 'cc2611-logico-006', 'Problemas lógicos', null, '"Se o voo atrasar, o passageiro perde a conexão." Sabe-se que o passageiro não perdeu a conexão. O que se pode concluir?', null, '[{"letra": "A", "texto": "Nada se pode concluir.", "imagem_url": null}, {"letra": "B", "texto": "O voo não atrasou.", "imagem_url": null}, {"letra": "C", "texto": "O voo atrasou.", "imagem_url": null}, {"letra": "D", "texto": "O passageiro chegou adiantado.", "imagem_url": null}]'::jsonb, 'B', 'Se P então Q; não Q, logo não P. Se o voo tivesse atrasado, a conexão teria sido perdida.', false),
('logico', 'cc2611-logico-007', 'Problemas lógicos', null, 'Qual é a negação da frase "Todos os comissários falam inglês"?', null, '[{"letra": "A", "texto": "Todos os comissários não falam inglês.", "imagem_url": null}, {"letra": "B", "texto": "Nenhum comissário fala inglês.", "imagem_url": null}, {"letra": "C", "texto": "Pelo menos um comissário não fala inglês.", "imagem_url": null}, {"letra": "D", "texto": "Alguns comissários falam inglês.", "imagem_url": null}]'::jsonb, 'C', 'Para negar "todos", basta um exemplo contrário: existe pelo menos um que não fala.', false),
('logico', 'cc2611-logico-008', 'Problemas lógicos', null, 'Todo piloto é tripulante. Nenhum tripulante é passageiro. Qual conclusão é necessariamente verdadeira?', null, '[{"letra": "A", "texto": "Alguns passageiros são pilotos.", "imagem_url": null}, {"letra": "B", "texto": "Alguns pilotos são passageiros.", "imagem_url": null}, {"letra": "C", "texto": "Todo tripulante é piloto.", "imagem_url": null}, {"letra": "D", "texto": "Nenhum piloto é passageiro.", "imagem_url": null}]'::jsonb, 'D', 'Os pilotos estão dentro do grupo dos tripulantes, que não tem nenhum passageiro. Logo, nenhum piloto é passageiro.', false),
('logico', 'cc2611-logico-009', 'Problemas lógicos', null, 'Um voo sai de São Paulo às 22h (horário de Brasília) e dura 11 horas. O destino está 4 horas à frente de Brasília. Qual é a hora local da chegada?', null, '[{"letra": "A", "texto": "7h do dia seguinte", "imagem_url": null}, {"letra": "B", "texto": "13h do dia seguinte", "imagem_url": null}, {"letra": "C", "texto": "17h do dia seguinte", "imagem_url": null}, {"letra": "D", "texto": "9h do dia seguinte", "imagem_url": null}]'::jsonb, 'B', '22h + 11h = 9h do dia seguinte em Brasília. No destino são 4 horas a mais: 13h.', false),
('logico', 'cc2611-logico-010', 'Problemas lógicos', null, 'Uma comissária trabalha 3 dias e folga 1, sempre nessa ordem. A primeira folga do mês foi no dia 1. Qual é a primeira folga depois do dia 20?', null, '[{"letra": "A", "texto": "Dia 22", "imagem_url": null}, {"letra": "B", "texto": "Dia 20", "imagem_url": null}, {"letra": "C", "texto": "Dia 24", "imagem_url": null}, {"letra": "D", "texto": "Dia 21", "imagem_url": null}]'::jsonb, 'D', 'As folgas acontecem a cada 4 dias: 1, 5, 9, 13, 17, 21.', false),
('logico', 'cc2611-logico-011', 'Problemas lógicos', null, 'O filho do único irmão do meu pai é meu:', null, '[{"letra": "A", "texto": "tio", "imagem_url": null}, {"letra": "B", "texto": "irmão", "imagem_url": null}, {"letra": "C", "texto": "sobrinho", "imagem_url": null}, {"letra": "D", "texto": "primo", "imagem_url": null}]'::jsonb, 'D', 'O único irmão do meu pai é meu tio. O filho do meu tio é meu primo.', false),
('logico', 'cc2611-logico-012', 'Problemas lógicos', null, 'Ana, Bia e Cris trabalham em companhias diferentes: Azul, GOL e LATAM. Ana não trabalha na GOL. Bia trabalha na LATAM. Onde trabalha Cris?', null, '[{"letra": "A", "texto": "GOL", "imagem_url": null}, {"letra": "B", "texto": "LATAM", "imagem_url": null}, {"letra": "C", "texto": "Azul", "imagem_url": null}, {"letra": "D", "texto": "Não é possível saber", "imagem_url": null}]'::jsonb, 'A', 'Bia está na LATAM. Ana não está na GOL, então está na Azul. Sobra a GOL para Cris.', false),
('logico', 'cc2611-logico-013', 'Problemas lógicos', null, 'Seis tripulantes se cumprimentam com um aperto de mão, cada um com todos os outros, uma única vez. Quantos apertos de mão acontecem?', null, '[{"letra": "A", "texto": "12", "imagem_url": null}, {"letra": "B", "texto": "15", "imagem_url": null}, {"letra": "C", "texto": "36", "imagem_url": null}, {"letra": "D", "texto": "30", "imagem_url": null}]'::jsonb, 'B', 'Cada par se cumprimenta uma vez: 6 × 5 ÷ 2 = 15.', false),
('logico', 'cc2611-logico-014', 'Problemas lógicos', null, 'Um carrinho de bordo tem três vezes mais latas de suco do que de refrigerante. No total são 48 latas. Quantas são de refrigerante?', null, '[{"letra": "A", "texto": "36", "imagem_url": null}, {"letra": "B", "texto": "12", "imagem_url": null}, {"letra": "C", "texto": "24", "imagem_url": null}, {"letra": "D", "texto": "16", "imagem_url": null}]'::jsonb, 'B', 'Refrigerante = x, suco = 3x. x + 3x = 48, então x = 12.', false),
('logico', 'cc2611-logico-015', 'Problemas lógicos', null, 'Se anteontem foi sábado, que dia será depois de amanhã?', null, '[{"letra": "A", "texto": "Quinta-feira", "imagem_url": null}, {"letra": "B", "texto": "Terça-feira", "imagem_url": null}, {"letra": "C", "texto": "Quarta-feira", "imagem_url": null}, {"letra": "D", "texto": "Domingo", "imagem_url": null}]'::jsonb, 'C', 'Anteontem sábado, ontem domingo, hoje segunda, amanhã terça, depois de amanhã quarta.', false),
('logico', 'cc2611-logico-016', 'Problemas lógicos', null, 'Paulo é mais alto que Rui. Rui é mais baixo que Saulo. Saulo é mais baixo que Paulo. Quem é o mais baixo?', null, '[{"letra": "A", "texto": "Não é possível saber", "imagem_url": null}, {"letra": "B", "texto": "Rui", "imagem_url": null}, {"letra": "C", "texto": "Paulo", "imagem_url": null}, {"letra": "D", "texto": "Saulo", "imagem_url": null}]'::jsonb, 'B', 'Rui é mais baixo que Paulo e que Saulo, então é o mais baixo dos três.', false),
('logico', 'cc2611-logico-017', 'Problemas lógicos', null, '"Se é voo internacional, a tripulação leva passaporte." Qual frase é equivalente a essa?', null, '[{"letra": "A", "texto": "Se a tripulação leva passaporte, é voo internacional.", "imagem_url": null}, {"letra": "B", "texto": "Se a tripulação não leva passaporte, não é voo internacional.", "imagem_url": null}, {"letra": "C", "texto": "Se não é voo internacional, a tripulação não leva passaporte.", "imagem_url": null}, {"letra": "D", "texto": "A tripulação sempre leva passaporte.", "imagem_url": null}]'::jsonb, 'B', '"Se P então Q" equivale a "se não Q então não P" (contrapositiva). As outras trocam a ordem e não são equivalentes.', false),
('logico', 'cc2611-logico-018', 'Problemas lógicos', null, 'Uma xícara quebrou e quatro amigos falaram: A: "Foi o B". B: "Foi o D". C: "Não fui eu". D: "O B está mentindo". Só um deles diz a verdade. Quem quebrou a xícara?', null, '[{"letra": "A", "texto": "B", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "A", "imagem_url": null}]'::jsonb, 'C', 'Se foi C: A mente, B mente, C mente e D fala a verdade (B mentiu). Só uma verdade, como pede o enunciado. Nos outros casos aparecem duas verdades ou mais.', false),
('logico', 'cc2611-logico-019', 'Problemas lógicos', null, 'De quantas maneiras 4 comissários podem ser distribuídos nas 4 portas do avião, um em cada porta?', null, '[{"letra": "A", "texto": "24", "imagem_url": null}, {"letra": "B", "texto": "12", "imagem_url": null}, {"letra": "C", "texto": "16", "imagem_url": null}, {"letra": "D", "texto": "4", "imagem_url": null}]'::jsonb, 'A', '4 opções para a primeira porta, 3 para a segunda, 2 para a terceira e 1 para a última: 4 × 3 × 2 × 1 = 24.', false),
('logico', 'cc2611-logico-020', 'Problemas lógicos', null, 'Nas três primeiras provas, uma aluna tirou 6, 7 e 8. Que nota ela precisa na quarta prova para ter média 7,5?', null, '[{"letra": "A", "texto": "9", "imagem_url": null}, {"letra": "B", "texto": "8", "imagem_url": null}, {"letra": "C", "texto": "8,5", "imagem_url": null}, {"letra": "D", "texto": "10", "imagem_url": null}]'::jsonb, 'A', 'Média 7,5 em 4 provas = 30 pontos. Ela já tem 21. Precisa de 30 − 21 = 9.', false),
('logico', 'cc2611-logico-021', 'Problemas lógicos', null, 'Nenhum A é B. Todo C é A. Qual conclusão é necessariamente verdadeira?', null, '[{"letra": "A", "texto": "Todo B é C.", "imagem_url": null}, {"letra": "B", "texto": "Todo A é C.", "imagem_url": null}, {"letra": "C", "texto": "Algum C é B.", "imagem_url": null}, {"letra": "D", "texto": "Nenhum C é B.", "imagem_url": null}]'::jsonb, 'D', 'Todo C está dentro de A, e nada de A é B. Então nenhum C é B.', false),
('logico', 'cc2611-logico-022', 'Problemas lógicos', null, 'Em um dado comum, as faces opostas somam 7. Se a face de cima mostra 2, qual número está na face de baixo?', null, '[{"letra": "A", "texto": "4", "imagem_url": null}, {"letra": "B", "texto": "6", "imagem_url": null}, {"letra": "C", "texto": "3", "imagem_url": null}, {"letra": "D", "texto": "5", "imagem_url": null}]'::jsonb, 'D', 'Faces opostas somam 7: 7 − 2 = 5.', false),
('logico', 'cc2611-logico-023', 'Problemas lógicos', null, 'Na fila de embarque, Joana é a 8ª pessoa contando da frente e a 12ª contando de trás. Quantas pessoas há na fila?', null, '[{"letra": "A", "texto": "21", "imagem_url": null}, {"letra": "B", "texto": "20", "imagem_url": null}, {"letra": "C", "texto": "18", "imagem_url": null}, {"letra": "D", "texto": "19", "imagem_url": null}]'::jsonb, 'D', '7 pessoas na frente dela + ela + 11 atrás: 7 + 1 + 11 = 19.', false),
('logico', 'cc2611-logico-024', 'Problemas lógicos', null, 'Uma mãe tem 36 anos e o filho tem 6. Daqui a quantos anos a mãe terá o triplo da idade do filho?', null, '[{"letra": "A", "texto": "10", "imagem_url": null}, {"letra": "B", "texto": "9", "imagem_url": null}, {"letra": "C", "texto": "6", "imagem_url": null}, {"letra": "D", "texto": "12", "imagem_url": null}]'::jsonb, 'B', '36 + x = 3 × (6 + x) → 36 + x = 18 + 3x → x = 9. Ela terá 45 e ele 15.', false),
('logico', 'cc2611-logico-025', 'Problemas lógicos', null, 'Em uma ilha, quem é sincero sempre fala a verdade e quem é mentiroso sempre mente. Ana diz: "Pelo menos um de nós dois, eu e o Beto, é mentiroso". O que se pode concluir?', null, '[{"letra": "A", "texto": "Os dois são mentirosos.", "imagem_url": null}, {"letra": "B", "texto": "Ana é sincera e Beto é mentiroso.", "imagem_url": null}, {"letra": "C", "texto": "Os dois são sinceros.", "imagem_url": null}, {"letra": "D", "texto": "Ana é mentirosa e Beto é sincero.", "imagem_url": null}]'::jsonb, 'B', 'Se Ana mentisse, a frase seria falsa e nenhum dos dois seria mentiroso, o que é contraditório. Então Ana é sincera e a frase é verdadeira: Beto é mentiroso.', false),
('logico', 'cc2611-logico-026', 'Problemas lógicos', null, '"O avião só decola se a porta estiver fechada." O avião decolou. O que se pode concluir?', null, '[{"letra": "A", "texto": "Nada se pode concluir.", "imagem_url": null}, {"letra": "B", "texto": "A porta estava fechada.", "imagem_url": null}, {"letra": "C", "texto": "A porta estava aberta.", "imagem_url": null}, {"letra": "D", "texto": "A porta foi fechada depois da decolagem.", "imagem_url": null}]'::jsonb, 'B', '"Só se" indica condição necessária: decolar exige porta fechada.', false),
('logico', 'cc2611-logico-027', 'Problemas lógicos', null, 'Os voos W, X, Y e Z partem em horários diferentes. X parte antes de Y e depois de W. Z parte depois de Y. Qual voo parte primeiro?', null, '[{"letra": "A", "texto": "Z", "imagem_url": null}, {"letra": "B", "texto": "W", "imagem_url": null}, {"letra": "C", "texto": "X", "imagem_url": null}, {"letra": "D", "texto": "Y", "imagem_url": null}]'::jsonb, 'B', 'W antes de X, X antes de Y, Y antes de Z: W, X, Y, Z.', false),
('logico', 'cc2611-logico-028', 'Problemas lógicos', null, 'Em um ano, 1º de março caiu numa quarta-feira. Em que dia da semana caiu 1º de abril?', null, '[{"letra": "A", "texto": "Quarta-feira", "imagem_url": null}, {"letra": "B", "texto": "Sexta-feira", "imagem_url": null}, {"letra": "C", "texto": "Domingo", "imagem_url": null}, {"letra": "D", "texto": "Sábado", "imagem_url": null}]'::jsonb, 'D', 'Março tem 31 dias: 31 = 4 semanas + 3 dias. Quarta + 3 dias = sábado.', false),
('logico', 'cc2611-logico-029', 'Problemas lógicos', null, 'Em uma caixa há 3 bolas vermelhas e 5 azuis. Tirando uma bola ao acaso, qual é a chance de ela ser vermelha?', null, '[{"letra": "A", "texto": "5/8", "imagem_url": null}, {"letra": "B", "texto": "3/5", "imagem_url": null}, {"letra": "C", "texto": "1/3", "imagem_url": null}, {"letra": "D", "texto": "3/8", "imagem_url": null}]'::jsonb, 'D', 'São 3 vermelhas em 8 bolas no total: 3/8.', false),
('logico', 'cc2611-logico-030', 'Problemas lógicos', null, 'Com notas de R$ 5 e de R$ 10, de quantas formas diferentes é possível pagar exatamente R$ 20?', null, '[{"letra": "A", "texto": "2", "imagem_url": null}, {"letra": "B", "texto": "5", "imagem_url": null}, {"letra": "C", "texto": "3", "imagem_url": null}, {"letra": "D", "texto": "4", "imagem_url": null}]'::jsonb, 'C', 'Quatro notas de 5; uma de 10 e duas de 5; duas de 10. São 3 formas.', false),
('logico', 'cc2611-logico-031', 'Problemas lógicos', null, 'Rafael, Sílvio e Tiago são comandante, copiloto e engenheiro de voo, não necessariamente nessa ordem. O copiloto é filho único e é o mais baixo dos três. Sílvio é casado com a irmã de Tiago e é mais alto que o comandante. Quem é o comandante?', null, '[{"letra": "A", "texto": "Sílvio", "imagem_url": null}, {"letra": "B", "texto": "Rafael", "imagem_url": null}, {"letra": "C", "texto": "Tiago", "imagem_url": null}, {"letra": "D", "texto": "Não é possível saber", "imagem_url": null}]'::jsonb, 'C', 'Tiago tem irmã, então não é o copiloto (filho único). Sílvio é mais alto que o comandante, então não é o comandante nem o copiloto (o mais baixo): é o engenheiro. Rafael é o copiloto e Tiago, o comandante.', false),
('logico', 'cc2611-logico-032', 'Problemas lógicos', null, 'Todos os candidatos que passaram na entrevista passaram na dinâmica. Lucas não passou na dinâmica. O que se pode concluir?', null, '[{"letra": "A", "texto": "Lucas não passou na entrevista.", "imagem_url": null}, {"letra": "B", "texto": "Lucas passou nas duas etapas.", "imagem_url": null}, {"letra": "C", "texto": "Lucas passou na entrevista.", "imagem_url": null}, {"letra": "D", "texto": "Nada se pode concluir.", "imagem_url": null}]'::jsonb, 'A', 'Quem passou na entrevista está dentro do grupo que passou na dinâmica. Como Lucas está fora desse grupo, ele não passou na entrevista.', false),
('logico', 'cc2611-logico-033', 'Problemas lógicos', null, 'Numa gaveta escura há meias pretas e brancas misturadas. Quantas meias é preciso tirar, no mínimo, para ter certeza de formar um par da mesma cor?', null, '[{"letra": "A", "texto": "2", "imagem_url": null}, {"letra": "B", "texto": "3", "imagem_url": null}, {"letra": "C", "texto": "4", "imagem_url": null}, {"letra": "D", "texto": "5", "imagem_url": null}]'::jsonb, 'B', 'Com duas meias elas podem ser de cores diferentes. A terceira repete obrigatoriamente uma das duas cores.', false),
('logico', 'cc2611-logico-034', 'Problemas lógicos', null, 'Três comissários arrumam a cabine em 12 minutos. Trabalhando no mesmo ritmo, em quanto tempo 4 comissários arrumam a mesma cabine?', null, '[{"letra": "A", "texto": "9 minutos", "imagem_url": null}, {"letra": "B", "texto": "10 minutos", "imagem_url": null}, {"letra": "C", "texto": "8 minutos", "imagem_url": null}, {"letra": "D", "texto": "16 minutos", "imagem_url": null}]'::jsonb, 'A', 'O trabalho total é 3 × 12 = 36 "minutos-comissário". Com 4 pessoas: 36 ÷ 4 = 9 minutos.', false),
('logico', 'cc2611-logico-035', 'Problemas lógicos', null, 'Que horas são quando faltam 25 minutos para as 15h?', null, '[{"letra": "A", "texto": "14h35", "imagem_url": null}, {"letra": "B", "texto": "14h25", "imagem_url": null}, {"letra": "C", "texto": "15h25", "imagem_url": null}, {"letra": "D", "texto": "13h35", "imagem_url": null}]'::jsonb, 'A', '15h − 25 minutos = 14h35.', false),
('logico', 'cc2611-logico-036', 'Problemas lógicos', null, 'Toda pessoa de crachá azul trabalha na manutenção. Marta trabalha na manutenção. O que se pode concluir?', null, '[{"letra": "A", "texto": "Marta usa crachá azul.", "imagem_url": null}, {"letra": "B", "texto": "Marta não usa crachá azul.", "imagem_url": null}, {"letra": "C", "texto": "Nada se pode concluir sobre a cor do crachá de Marta.", "imagem_url": null}, {"letra": "D", "texto": "Todos da manutenção usam crachá azul.", "imagem_url": null}]'::jsonb, 'C', 'A regra diz que todo crachá azul é da manutenção, mas não que todo funcionário da manutenção usa crachá azul.', false),
('logico', 'cc2611-logico-037', 'Problemas lógicos', null, 'Em uma corrida, você ultrapassa quem está em segundo lugar. Em que posição você fica?', null, '[{"letra": "A", "texto": "Em terceiro lugar", "imagem_url": null}, {"letra": "B", "texto": "Em segundo lugar", "imagem_url": null}, {"letra": "C", "texto": "Em primeiro lugar", "imagem_url": null}, {"letra": "D", "texto": "Depende de quantos corredores há", "imagem_url": null}]'::jsonb, 'B', 'Você toma o lugar de quem ultrapassou: o segundo.', false),
('logico', 'cc2611-logico-038', 'Problemas lógicos', null, 'Em um voo longo, 3 comissários dividem 18 horas de descanso em turnos iguais e seguidos. O primeiro turno começa às 20h. A que horas começa o terceiro turno?', null, '[{"letra": "A", "texto": "14h", "imagem_url": null}, {"letra": "B", "texto": "6h", "imagem_url": null}, {"letra": "C", "texto": "2h", "imagem_url": null}, {"letra": "D", "texto": "8h", "imagem_url": null}]'::jsonb, 'D', 'Cada turno tem 18 ÷ 3 = 6 horas: 20h, 2h e 8h.', false),
('logico', 'cc2611-logico-039', 'Problemas lógicos', null, 'A mala A pesa o dobro da mala B. A mala C pesa 4 kg a menos que a A. As três juntas pesam 46 kg. Quanto pesa a mala B?', null, '[{"letra": "A", "texto": "16 kg", "imagem_url": null}, {"letra": "B", "texto": "20 kg", "imagem_url": null}, {"letra": "C", "texto": "10 kg", "imagem_url": null}, {"letra": "D", "texto": "12 kg", "imagem_url": null}]'::jsonb, 'C', 'B = x, A = 2x, C = 2x − 4. x + 2x + 2x − 4 = 46 → 5x = 50 → x = 10.', false),
('logico', 'cc2611-logico-040', 'Problemas lógicos', null, 'Se todo dia que chove o voo atrasa, e hoje o voo não atrasou, então:', null, '[{"letra": "A", "texto": "hoje choveu.", "imagem_url": null}, {"letra": "B", "texto": "hoje não choveu.", "imagem_url": null}, {"letra": "C", "texto": "amanhã vai chover.", "imagem_url": null}, {"letra": "D", "texto": "o voo atrasa só quando chove.", "imagem_url": null}]'::jsonb, 'B', 'Chuva implica atraso. Sem atraso, não houve chuva (contrapositiva).', false),
('logico', 'cc2611-logico-041', 'Sequências', null, 'Complete a sequência: 2, 6, 18, 54, ?', null, '[{"letra": "A", "texto": "108", "imagem_url": null}, {"letra": "B", "texto": "72", "imagem_url": null}, {"letra": "C", "texto": "216", "imagem_url": null}, {"letra": "D", "texto": "162", "imagem_url": null}]'::jsonb, 'D', 'Cada número é o anterior × 3: 54 × 3 = 162.', false),
('logico', 'cc2611-logico-042', 'Sequências', null, 'Complete a sequência: 3, 5, 9, 17, 33, ?', null, '[{"letra": "A", "texto": "64", "imagem_url": null}, {"letra": "B", "texto": "66", "imagem_url": null}, {"letra": "C", "texto": "65", "imagem_url": null}, {"letra": "D", "texto": "49", "imagem_url": null}]'::jsonb, 'C', 'Cada número é o anterior × 2 − 1: 33 × 2 − 1 = 65.', false),
('logico', 'cc2611-logico-043', 'Sequências', null, 'Complete a sequência: 1, 4, 9, 16, 25, ?', null, '[{"letra": "A", "texto": "36", "imagem_url": null}, {"letra": "B", "texto": "30", "imagem_url": null}, {"letra": "C", "texto": "49", "imagem_url": null}, {"letra": "D", "texto": "35", "imagem_url": null}]'::jsonb, 'A', 'São os quadrados: 1², 2², 3², 4², 5², 6² = 36.', false),
('logico', 'cc2611-logico-044', 'Sequências', null, 'Complete a sequência: 100, 95, 85, 70, 50, ?', null, '[{"letra": "A", "texto": "35", "imagem_url": null}, {"letra": "B", "texto": "20", "imagem_url": null}, {"letra": "C", "texto": "25", "imagem_url": null}, {"letra": "D", "texto": "30", "imagem_url": null}]'::jsonb, 'C', 'As diferenças crescem de 5 em 5: −5, −10, −15, −20, −25. 50 − 25 = 25.', false),
('logico', 'cc2611-logico-045', 'Sequências', null, 'Complete a sequência: 2, 3, 5, 7, 11, 13, ?', null, '[{"letra": "A", "texto": "19", "imagem_url": null}, {"letra": "B", "texto": "16", "imagem_url": null}, {"letra": "C", "texto": "17", "imagem_url": null}, {"letra": "D", "texto": "15", "imagem_url": null}]'::jsonb, 'C', 'São os números primos em ordem. Depois do 13 vem o 17.', false),
('logico', 'cc2611-logico-046', 'Sequências', null, 'Complete a sequência: 1, 1, 2, 3, 5, 8, 13, ?', null, '[{"letra": "A", "texto": "18", "imagem_url": null}, {"letra": "B", "texto": "20", "imagem_url": null}, {"letra": "C", "texto": "26", "imagem_url": null}, {"letra": "D", "texto": "21", "imagem_url": null}]'::jsonb, 'D', 'Cada número é a soma dos dois anteriores: 8 + 13 = 21.', false),
('logico', 'cc2611-logico-047', 'Sequências', null, 'Complete a sequência: 5, 10, 8, 16, 14, ?', null, '[{"letra": "A", "texto": "30", "imagem_url": null}, {"letra": "B", "texto": "22", "imagem_url": null}, {"letra": "C", "texto": "12", "imagem_url": null}, {"letra": "D", "texto": "28", "imagem_url": null}]'::jsonb, 'D', 'Alterna × 2 e − 2: 5×2=10, 10−2=8, 8×2=16, 16−2=14, 14×2=28.', false),
('logico', 'cc2611-logico-048', 'Sequências', null, 'Complete a sequência de letras: A, C, F, J, O, ?', null, '[{"letra": "A", "texto": "V", "imagem_url": null}, {"letra": "B", "texto": "S", "imagem_url": null}, {"letra": "C", "texto": "T", "imagem_url": null}, {"letra": "D", "texto": "U", "imagem_url": null}]'::jsonb, 'D', 'Os saltos aumentam: +2, +3, +4, +5, +6. De O (15ª letra) + 6 = U (21ª).', false),
('logico', 'cc2611-logico-049', 'Sequências', null, 'Complete a sequência de letras: Z, X, V, T, ?', null, '[{"letra": "A", "texto": "R", "imagem_url": null}, {"letra": "B", "texto": "P", "imagem_url": null}, {"letra": "C", "texto": "Q", "imagem_url": null}, {"letra": "D", "texto": "S", "imagem_url": null}]'::jsonb, 'A', 'Volta de duas em duas letras no alfabeto: Z, X, V, T, R.', false),
('logico', 'cc2611-logico-050', 'Sequências', null, 'Complete a sequência: AZ, BY, CX, DW, ?', null, '[{"letra": "A", "texto": "EV", "imagem_url": null}, {"letra": "B", "texto": "EW", "imagem_url": null}, {"letra": "C", "texto": "EU", "imagem_url": null}, {"letra": "D", "texto": "FV", "imagem_url": null}]'::jsonb, 'A', 'A primeira letra avança no alfabeto e a segunda volta: E e V.', false),
('logico', 'cc2611-logico-051', 'Sequências', null, 'Complete a sequência: 81, 27, 9, 3, ?', null, '[{"letra": "A", "texto": "1/3", "imagem_url": null}, {"letra": "B", "texto": "2", "imagem_url": null}, {"letra": "C", "texto": "0", "imagem_url": null}, {"letra": "D", "texto": "1", "imagem_url": null}]'::jsonb, 'D', 'Cada número é o anterior ÷ 3: 3 ÷ 3 = 1.', false),
('logico', 'cc2611-logico-052', 'Sequências', null, 'Complete a sequência: 7, 14, 28, 56, ?', null, '[{"letra": "A", "texto": "112", "imagem_url": null}, {"letra": "B", "texto": "102", "imagem_url": null}, {"letra": "C", "texto": "84", "imagem_url": null}, {"letra": "D", "texto": "70", "imagem_url": null}]'::jsonb, 'A', 'Cada número dobra: 56 × 2 = 112.', false),
('logico', 'cc2611-logico-053', 'Sequências', null, 'Complete a sequência: 4, 7, 12, 19, 28, ?', null, '[{"letra": "A", "texto": "37", "imagem_url": null}, {"letra": "B", "texto": "38", "imagem_url": null}, {"letra": "C", "texto": "40", "imagem_url": null}, {"letra": "D", "texto": "39", "imagem_url": null}]'::jsonb, 'D', 'As diferenças são os ímpares 3, 5, 7, 9, 11: 28 + 11 = 39.', false),
