('logico', 'cc2611-logico-055', 'Sequências', null, 'Complete a sequência: 2, 5, 11, 23, 47, ?', null, '[{"letra": "A", "texto": "94", "imagem_url": null}, {"letra": "B", "texto": "71", "imagem_url": null}, {"letra": "C", "texto": "95", "imagem_url": null}, {"letra": "D", "texto": "96", "imagem_url": null}]'::jsonb, 'C', 'Cada número é o anterior × 2 + 1: 47 × 2 + 1 = 95.', false),
('logico', 'cc2611-logico-056', 'Sequências', null, 'Complete a sequência: 10, 13, 11, 14, 12, ?', null, '[{"letra": "A", "texto": "13", "imagem_url": null}, {"letra": "B", "texto": "10", "imagem_url": null}, {"letra": "C", "texto": "15", "imagem_url": null}, {"letra": "D", "texto": "16", "imagem_url": null}]'::jsonb, 'C', 'Alterna + 3 e − 2: 12 + 3 = 15.', false),
('logico', 'cc2611-logico-057', 'Sequências', null, 'Os voos de uma rota seguem o padrão GRU101, GRU103, GRU107, GRU113, ? Qual é o próximo?', null, '[{"letra": "A", "texto": "GRU121", "imagem_url": null}, {"letra": "B", "texto": "GRU119", "imagem_url": null}, {"letra": "C", "texto": "GRU117", "imagem_url": null}, {"letra": "D", "texto": "GRU123", "imagem_url": null}]'::jsonb, 'A', 'Os saltos crescem de 2 em 2: +2, +4, +6, +8. 113 + 8 = 121.', false),
('logico', 'cc2611-logico-058', 'Sequências', null, 'Complete a sequência: 1, 2, 6, 24, 120, ?', null, '[{"letra": "A", "texto": "240", "imagem_url": null}, {"letra": "B", "texto": "840", "imagem_url": null}, {"letra": "C", "texto": "720", "imagem_url": null}, {"letra": "D", "texto": "600", "imagem_url": null}]'::jsonb, 'C', 'Multiplica por 2, 3, 4, 5 e depois por 6: 120 × 6 = 720.', false),
('logico', 'cc2611-logico-059', 'Sequências', null, 'Complete a sequência: 3, 6, 11, 18, 27, ?', null, '[{"letra": "A", "texto": "39", "imagem_url": null}, {"letra": "B", "texto": "38", "imagem_url": null}, {"letra": "C", "texto": "36", "imagem_url": null}, {"letra": "D", "texto": "40", "imagem_url": null}]'::jsonb, 'B', 'As diferenças são 3, 5, 7, 9, 11: 27 + 11 = 38.', false),
('logico', 'cc2611-logico-060', 'Sequências', null, 'Complete a sequência: B2, D4, F6, H8, ?', null, '[{"letra": "A", "texto": "J10", "imagem_url": null}, {"letra": "B", "texto": "I9", "imagem_url": null}, {"letra": "C", "texto": "J9", "imagem_url": null}, {"letra": "D", "texto": "K10", "imagem_url": null}]'::jsonb, 'A', 'A letra avança de duas em duas e o número acompanha a posição dela no alfabeto: J é a 10ª letra.', false),
('logico', 'cc2611-logico-061', 'Sequências', null, 'Complete a sequência: jan, mar, mai, jul, ?', null, '[{"letra": "A", "texto": "ago", "imagem_url": null}, {"letra": "B", "texto": "set", "imagem_url": null}, {"letra": "C", "texto": "jun", "imagem_url": null}, {"letra": "D", "texto": "out", "imagem_url": null}]'::jsonb, 'B', 'Pula um mês a cada vez: janeiro, março, maio, julho, setembro.', false),
('logico', 'cc2611-logico-062', 'Sequências', null, 'Complete a sequência: 64, 32, 48, 24, 36, ?', null, '[{"letra": "A", "texto": "18", "imagem_url": null}, {"letra": "B", "texto": "54", "imagem_url": null}, {"letra": "C", "texto": "12", "imagem_url": null}, {"letra": "D", "texto": "27", "imagem_url": null}]'::jsonb, 'A', 'Alterna ÷ 2 e × 1,5: 64÷2=32, 32×1,5=48, 48÷2=24, 24×1,5=36, 36÷2=18.', false),
('logico', 'cc2611-logico-063', 'Sequências', null, 'Complete a sequência: 2, 4, 12, 48, 240, ?', null, '[{"letra": "A", "texto": "1200", "imagem_url": null}, {"letra": "B", "texto": "960", "imagem_url": null}, {"letra": "C", "texto": "1440", "imagem_url": null}, {"letra": "D", "texto": "480", "imagem_url": null}]'::jsonb, 'C', 'Multiplica por 2, 3, 4, 5 e 6: 240 × 6 = 1440.', false),
('logico', 'cc2611-logico-064', 'Sequências', null, 'Complete a sequência: 0, 3, 8, 15, 24, ?', null, '[{"letra": "A", "texto": "36", "imagem_url": null}, {"letra": "B", "texto": "35", "imagem_url": null}, {"letra": "C", "texto": "30", "imagem_url": null}, {"letra": "D", "texto": "33", "imagem_url": null}]'::jsonb, 'B', 'Cada número é um quadrado menos 1: 1−1, 4−1, 9−1, 16−1, 25−1, 36−1 = 35.', false),
