('ingles', 'cc2611-ingles-026', 'Inglês', null, 'Choose the correct option: "We have ___ time before boarding, so please hurry."', null, '[{"letra": "A", "texto": "many", "imagem_url": null}, {"letra": "B", "texto": "a few", "imagem_url": null}, {"letra": "C", "texto": "little", "imagem_url": null}, {"letra": "D", "texto": "few", "imagem_url": null}]'::jsonb, 'C', 'Time é incontável: little (pouco). Few é para contáveis.', false),
