('ingles', 'cc2611-ingles-028', 'Inglês', null, 'Choose the correct option: "How ___ bags are you checking in?"', null, '[{"letra": "A", "texto": "long", "imagem_url": null}, {"letra": "B", "texto": "much", "imagem_url": null}, {"letra": "C", "texto": "many", "imagem_url": null}, {"letra": "D", "texto": "often", "imagem_url": null}]'::jsonb, 'C', 'Bags é contável: how many.', false),
('ingles', 'cc2611-ingles-029', 'Inglês', null, 'Choose the correct option: "You ___ smoke on board. It is forbidden."', null, '[{"letra": "A", "texto": "don''t have to", "imagem_url": null}, {"letra": "B", "texto": "must not", "imagem_url": null}, {"letra": "C", "texto": "needn''t", "imagem_url": null}, {"letra": "D", "texto": "mustn''t to", "imagem_url": null}]'::jsonb, 'B', 'Must not = proibição. Don''t have to = não é obrigatório.', false),
('ingles', 'cc2611-ingles-030', 'Inglês', null, 'Choose the correct option: "The captain asked us ___ our seats."', null, '[{"letra": "A", "texto": "to returning", "imagem_url": null}, {"letra": "B", "texto": "returning", "imagem_url": null}, {"letra": "C", "texto": "return", "imagem_url": null}, {"letra": "D", "texto": "to return to", "imagem_url": null}]'::jsonb, 'D', 'Ask someone to do something: asked us to return to our seats.', false),
('ingles', 'cc2611-ingles-031', 'Inglês', null, 'Choose the correct option: "I''m looking forward ___ you at the interview."', null, '[{"letra": "A", "texto": "meeting", "imagem_url": null}, {"letra": "B", "texto": "for meet", "imagem_url": null}, {"letra": "C", "texto": "to meet", "imagem_url": null}, {"letra": "D", "texto": "to meeting", "imagem_url": null}]'::jsonb, 'D', 'Look forward to + verbo com -ing.', false),
('ingles', 'cc2611-ingles-032', 'Inglês', null, 'Choose the correct option: "By the time we landed, the passengers ___ dinner."', null, '[{"letra": "A", "texto": "are already having", "imagem_url": null}, {"letra": "B", "texto": "have already had", "imagem_url": null}, {"letra": "C", "texto": "already have", "imagem_url": null}, {"letra": "D", "texto": "had already had", "imagem_url": null}]'::jsonb, 'D', 'Ação concluída antes de outra no passado: past perfect (had had).', false),
('ingles', 'cc2611-ingles-033', 'Inglês', null, 'Choose the correct option: "Neither the captain ___ the first officer was in the cockpit."', null, '[{"letra": "A", "texto": "nor", "imagem_url": null}, {"letra": "B", "texto": "and", "imagem_url": null}, {"letra": "C", "texto": "or", "imagem_url": null}, {"letra": "D", "texto": "but", "imagem_url": null}]'::jsonb, 'A', 'Neither ... nor = nem ... nem.', false),
('ingles', 'cc2611-ingles-034', 'Inglês', null, 'Choose the correct option: "This is the passenger ___ suitcase was lost."', null, '[{"letra": "A", "texto": "whose", "imagem_url": null}, {"letra": "B", "texto": "who", "imagem_url": null}, {"letra": "C", "texto": "who''s", "imagem_url": null}, {"letra": "D", "texto": "which", "imagem_url": null}]'::jsonb, 'A', 'Whose indica posse: o passageiro cuja mala foi perdida.', false),
('ingles', 'cc2611-ingles-035', 'Inglês', null, 'Choose the correct option: "Please fasten your seat belt ___ the sign is on."', null, '[{"letra": "A", "texto": "meanwhile", "imagem_url": null}, {"letra": "B", "texto": "during", "imagem_url": null}, {"letra": "C", "texto": "for", "imagem_url": null}, {"letra": "D", "texto": "while", "imagem_url": null}]'::jsonb, 'D', 'While + frase (sujeito + verbo). During + substantivo (during the flight).', false),
('ingles', 'cc2611-ingles-036', 'Inglês', null, 'Choose the correct option: "I would like ___ a vegetarian meal, please."', null, '[{"letra": "A", "texto": "to ordering", "imagem_url": null}, {"letra": "B", "texto": "ordering", "imagem_url": null}, {"letra": "C", "texto": "to order", "imagem_url": null}, {"letra": "D", "texto": "order", "imagem_url": null}]'::jsonb, 'C', 'Would like + to + verbo.', false),
('ingles', 'cc2611-ingles-037', 'Inglês', null, 'Choose the correct option: "The flight was cancelled ___ the storm."', null, '[{"letra": "A", "texto": "although", "imagem_url": null}, {"letra": "B", "texto": "because of", "imagem_url": null}, {"letra": "C", "texto": "because", "imagem_url": null}, {"letra": "D", "texto": "despite of", "imagem_url": null}]'::jsonb, 'B', 'Because of + substantivo. Because + frase.', false),
('ingles', 'cc2611-ingles-038', 'Inglês', null, 'Choose the correct option: "He has never ___ to Japan."', null, '[{"letra": "A", "texto": "go", "imagem_url": null}, {"letra": "B", "texto": "gone to be", "imagem_url": null}, {"letra": "C", "texto": "went", "imagem_url": null}, {"letra": "D", "texto": "been", "imagem_url": null}]'::jsonb, 'D', 'Have been to = já ter ido (e voltado). He has never been to Japan.', false),
('ingles', 'cc2611-ingles-039', 'Inglês', null, 'A passenger says: "I''m feeling dizzy." What is the best response?', null, '[{"letra": "A", "texto": "Please go to the lavatory.", "imagem_url": null}, {"letra": "B", "texto": "We will land soon, so don''t worry about it.", "imagem_url": null}, {"letra": "C", "texto": "That''s not my problem.", "imagem_url": null}, {"letra": "D", "texto": "I''m sorry to hear that. Please sit down and I''ll get you some water.", "imagem_url": null}]'::jsonb, 'D', 'Mostre empatia e ofereça ajuda imediata.', false),
('ingles', 'cc2611-ingles-040', 'Inglês', null, 'A passenger asks: "Can I use my phone now?" The aircraft is taxiing. What do you say?', null, '[{"letra": "A", "texto": "Yes, but please keep it in flight mode.", "imagem_url": null}, {"letra": "B", "texto": "No, phones are forbidden on all flights.", "imagem_url": null}, {"letra": "C", "texto": "Only if you turn the volume up.", "imagem_url": null}, {"letra": "D", "texto": "Yes, you can make calls during take-off.", "imagem_url": null}]'::jsonb, 'A', 'Hoje a maioria das companhias permite o celular em modo avião.', false),
('ingles', 'cc2611-ingles-041', 'Inglês', null, 'How do you politely tell a passenger that the chicken meal is no longer available?', null, '[{"letra": "A", "texto": "The chicken finished.", "imagem_url": null}, {"letra": "B", "texto": "I''m afraid we''ve run out of chicken. Would you like the pasta?", "imagem_url": null}, {"letra": "C", "texto": "There is no chicken, take the pasta.", "imagem_url": null}, {"letra": "D", "texto": "You are late for the chicken.", "imagem_url": null}]'::jsonb, 'B', '"I''m afraid..." suaviza a má notícia, e você oferece uma alternativa.', false),
('ingles', 'cc2611-ingles-042', 'Inglês', null, 'A passenger in the exit row asks why they must put their bag in the overhead bin. Best answer:', null, '[{"letra": "A", "texto": "Because I say so.", "imagem_url": null}, {"letra": "B", "texto": "The exit area must be kept clear in case of an emergency.", "imagem_url": null}, {"letra": "C", "texto": "Bags are not allowed on this airline.", "imagem_url": null}, {"letra": "D", "texto": "It is more comfortable for you.", "imagem_url": null}]'::jsonb, 'B', 'Explique o motivo de segurança com educação.', false),
('ingles', 'cc2611-ingles-043', 'Inglês', null, 'What does "Would you mind switching seats?" mean?', null, '[{"letra": "A", "texto": "Você gostaria de reclinar o assento?", "imagem_url": null}, {"letra": "B", "texto": "Você se importaria de trocar de assento?", "imagem_url": null}, {"letra": "C", "texto": "Seu assento está quebrado?", "imagem_url": null}, {"letra": "D", "texto": "Você pode desligar a luz?", "imagem_url": null}]'::jsonb, 'B', 'Would you mind + -ing = você se importaria de...', false),
('ingles', 'cc2611-ingles-044', 'Inglês', null, 'A passenger complains loudly about a delay. Which response is most professional?', null, '[{"letra": "A", "texto": "Calm down, everybody is waiting.", "imagem_url": null}, {"letra": "B", "texto": "It''s not our fault, it''s the airport.", "imagem_url": null}, {"letra": "C", "texto": "I completely understand your frustration. I''ll update you as soon as I have more information.", "imagem_url": null}, {"letra": "D", "texto": "Please stop shouting at me.", "imagem_url": null}]'::jsonb, 'C', 'Valide o sentimento e comprometa-se a informar.', false),
('ingles', 'cc2611-ingles-045', 'Inglês', null, 'Which sentence is a correct way to offer help?', null, '[{"letra": "A", "texto": "What do you want?", "imagem_url": null}, {"letra": "B", "texto": "Why are you calling me?", "imagem_url": null}, {"letra": "C", "texto": "Do you need something or not?", "imagem_url": null}, {"letra": "D", "texto": "How may I help you?", "imagem_url": null}]'::jsonb, 'D', 'How may I help you? é a forma cortês padrão.', false),
('ingles', 'cc2611-ingles-046', 'Inglês', null, '"Please stow your tray table" means:', null, '[{"letra": "A", "texto": "feche e trave a mesinha", "imagem_url": null}, {"letra": "B", "texto": "coloque a bandeja no chão", "imagem_url": null}, {"letra": "C", "texto": "abra a mesinha", "imagem_url": null}, {"letra": "D", "texto": "peça outra bandeja", "imagem_url": null}]'::jsonb, 'A', 'Stow = guardar, recolher. Tray table = mesinha.', false),
('ingles', 'cc2611-ingles-047', 'Inglês', null, 'A passenger asks: "Where is the nearest exit?" You point and say:', null, '[{"letra": "A", "texto": "Is two rows back you.", "imagem_url": null}, {"letra": "B", "texto": "It''s two rows behind you, on your right.", "imagem_url": null}, {"letra": "C", "texto": "It stays on the right two rows.", "imagem_url": null}, {"letra": "D", "texto": "It''s behind of you, at right.", "imagem_url": null}]'::jsonb, 'B', 'Behind you (sem of), on your right.', false),
('ingles', 'cc2611-ingles-048', 'Inglês', null, 'Which sentence would you use in an emergency evacuation?', null, '[{"letra": "A", "texto": "Please take your belongings and follow me.", "imagem_url": null}, {"letra": "B", "texto": "Excuse me, could you stand up?", "imagem_url": null}, {"letra": "C", "texto": "Release your seat belts! Get out!", "imagem_url": null}, {"letra": "D", "texto": "Would you kindly leave the aircraft?", "imagem_url": null}]'::jsonb, 'C', 'Em emergência, comandos curtos e firmes, sem bagagem.', false),
('ingles', 'cc2611-ingles-049', 'Inglês', null, 'A passenger says "I''d like a refill." What do they want?', null, '[{"letra": "A", "texto": "A new meal", "imagem_url": null}, {"letra": "B", "texto": "More of the same drink", "imagem_url": null}, {"letra": "C", "texto": "A blanket", "imagem_url": null}, {"letra": "D", "texto": "To change seats", "imagem_url": null}]'::jsonb, 'B', 'Refill = mais da mesma bebida.', false),
('ingles', 'cc2611-ingles-050', 'Inglês', null, 'What is the correct response to "Thank you for your help"?', null, '[{"letra": "A", "texto": "You welcome.", "imagem_url": null}, {"letra": "B", "texto": "You''re welcome. Enjoy your flight.", "imagem_url": null}, {"letra": "C", "texto": "No thanks.", "imagem_url": null}, {"letra": "D", "texto": "Is nothing.", "imagem_url": null}]'::jsonb, 'B', 'You''re welcome (com o verbo be).', false),
('ingles', 'cc2611-ingles-051', 'Inglês', 'Ladies and gentlemen, the captain has turned on the fasten seat belt sign. We are now crossing a zone of turbulence. Please return to your seats and keep your seat belts fastened. The lavatories should not be used at this time. Cabin service will resume as soon as conditions improve. Thank you.', 'According to the announcement, why should passengers return to their seats?', null, '[{"letra": "A", "texto": "Because meals will be served.", "imagem_url": null}, {"letra": "B", "texto": "Because the plane is about to land.", "imagem_url": null}, {"letra": "C", "texto": "Because the aircraft is crossing turbulence.", "imagem_url": null}, {"letra": "D", "texto": "Because the lavatories are closed for cleaning.", "imagem_url": null}]'::jsonb, 'C', '"We are now crossing a zone of turbulence."', false),
('ingles', 'cc2611-ingles-052', 'Inglês', 'Ladies and gentlemen, the captain has turned on the fasten seat belt sign. We are now crossing a zone of turbulence. Please return to your seats and keep your seat belts fastened. The lavatories should not be used at this time. Cabin service will resume as soon as conditions improve. Thank you.', 'What does the announcement say about the lavatories?', null, '[{"letra": "A", "texto": "They will be cleaned.", "imagem_url": null}, {"letra": "B", "texto": "They can be used normally.", "imagem_url": null}, {"letra": "C", "texto": "They are out of order.", "imagem_url": null}, {"letra": "D", "texto": "They should not be used at this time.", "imagem_url": null}]'::jsonb, 'D', '"The lavatories should not be used at this time."', false),
('ingles', 'cc2611-ingles-053', 'Inglês', 'Ladies and gentlemen, the captain has turned on the fasten seat belt sign. We are now crossing a zone of turbulence. Please return to your seats and keep your seat belts fastened. The lavatories should not be used at this time. Cabin service will resume as soon as conditions improve. Thank you.', 'When will cabin service resume?', null, '[{"letra": "A", "texto": "It will not resume.", "imagem_url": null}, {"letra": "B", "texto": "After landing.", "imagem_url": null}, {"letra": "C", "texto": "In ten minutes.", "imagem_url": null}, {"letra": "D", "texto": "As soon as conditions improve.", "imagem_url": null}]'::jsonb, 'D', '"Cabin service will resume as soon as conditions improve."', false),
('ingles', 'cc2611-ingles-054', 'Inglês', 'Good evening, ladies and gentlemen. Welcome to Lisbon. The local time is 6:25 a.m. and the temperature is 14 degrees Celsius. Please remain seated until the captain switches off the seat belt sign. Passengers connecting to Madrid should proceed to gate 18. Thank you for flying with us.', 'What is the local time in Lisbon?', null, '[{"letra": "A", "texto": "6:25 a.m.", "imagem_url": null}, {"letra": "B", "texto": "2:25 p.m.", "imagem_url": null}, {"letra": "C", "texto": "6:52 a.m.", "imagem_url": null}, {"letra": "D", "texto": "6:25 p.m.", "imagem_url": null}]'::jsonb, 'A', '"The local time is 6:25 a.m."', false),
('ingles', 'cc2611-ingles-055', 'Inglês', 'Good evening, ladies and gentlemen. Welcome to Lisbon. The local time is 6:25 a.m. and the temperature is 14 degrees Celsius. Please remain seated until the captain switches off the seat belt sign. Passengers connecting to Madrid should proceed to gate 18. Thank you for flying with us.', 'Where should passengers going to Madrid go?', null, '[{"letra": "A", "texto": "To gate 18", "imagem_url": null}, {"letra": "B", "texto": "To the transfer desk", "imagem_url": null}, {"letra": "C", "texto": "To the baggage claim", "imagem_url": null}, {"letra": "D", "texto": "To gate 80", "imagem_url": null}]'::jsonb, 'A', '"Passengers connecting to Madrid should proceed to gate 18."', false),
('ingles', 'cc2611-ingles-056', 'Inglês', 'Good evening, ladies and gentlemen. Welcome to Lisbon. The local time is 6:25 a.m. and the temperature is 14 degrees Celsius. Please remain seated until the captain switches off the seat belt sign. Passengers connecting to Madrid should proceed to gate 18. Thank you for flying with us.', 'Which word in the announcement means "permanecer"?', null, '[{"letra": "A", "texto": "proceed", "imagem_url": null}, {"letra": "B", "texto": "switch off", "imagem_url": null}, {"letra": "C", "texto": "remain", "imagem_url": null}, {"letra": "D", "texto": "connect", "imagem_url": null}]'::jsonb, 'C', 'Remain seated = permaneçam sentados.', false),
('ingles', 'cc2611-ingles-057', 'Inglês', 'Good evening, ladies and gentlemen. Welcome to Lisbon. The local time is 6:25 a.m. and the temperature is 14 degrees Celsius. Please remain seated until the captain switches off the seat belt sign. Passengers connecting to Madrid should proceed to gate 18. Thank you for flying with us.', 'What does the announcement contain that is inconsistent?', null, '[{"letra": "A", "texto": "The temperature is in Fahrenheit.", "imagem_url": null}, {"letra": "B", "texto": "It says \"Good evening\" but the local time is in the morning.", "imagem_url": null}, {"letra": "C", "texto": "There is no gate number.", "imagem_url": null}, {"letra": "D", "texto": "It does not mention the city.", "imagem_url": null}]'::jsonb, 'B', '6:25 a.m. é de manhã, então o correto seria "Good morning". Atenção a detalhes como esse nos testes.', false),
('ingles', 'cc2611-ingles-058', 'Inglês', 'Dear Ms. Carter,
