('ingles', 'cc2611-ingles-062', 'Inglês', null, 'In an interview, the recruiter says: "Tell me about yourself." What is the best approach?', null, '[{"letra": "A", "texto": "Say \"There is nothing special about me.\"", "imagem_url": null}, {"letra": "B", "texto": "Read your résumé word by word.", "imagem_url": null}, {"letra": "C", "texto": "Talk about your family and hobbies for ten minutes.", "imagem_url": null}, {"letra": "D", "texto": "Give a short summary of your background, experience and why you want the job.", "imagem_url": null}]'::jsonb, 'D', 'Resposta curta e profissional: quem você é, experiência e motivação.', false),
('ingles', 'cc2611-ingles-063', 'Inglês', null, 'Which answer best shows teamwork?', null, '[{"letra": "A", "texto": "Teamwork is not important to me.", "imagem_url": null}, {"letra": "B", "texto": "I prefer to work alone because it''s faster.", "imagem_url": null}, {"letra": "C", "texto": "I always do the work of my colleagues.", "imagem_url": null}, {"letra": "D", "texto": "In my last job, I helped a colleague finish a task so our team could meet the deadline.", "imagem_url": null}]'::jsonb, 'D', 'Dê um exemplo concreto e mostre o resultado para a equipe.', false),
('ingles', 'cc2611-ingles-064', 'Inglês', null, '"What are your strengths?" Which answer is the most appropriate?', null, '[{"letra": "A", "texto": "I''m perfect for every job.", "imagem_url": null}, {"letra": "B", "texto": "I don''t have any weaknesses.", "imagem_url": null}, {"letra": "C", "texto": "I like travelling for free.", "imagem_url": null}, {"letra": "D", "texto": "I''m calm under pressure and I enjoy helping people.", "imagem_url": null}]'::jsonb, 'D', 'Cite qualidades ligadas à função, sem exageros.', false),
('ingles', 'cc2611-ingles-065', 'Inglês', null, 'How do you say "Eu tenho experiência com atendimento ao cliente"?', null, '[{"letra": "A", "texto": "I has experience with customer attendance.", "imagem_url": null}, {"letra": "B", "texto": "I have experiences with client attendance.", "imagem_url": null}, {"letra": "C", "texto": "I have experience in customer service.", "imagem_url": null}, {"letra": "D", "texto": "I am experience in customer service.", "imagem_url": null}]'::jsonb, 'C', 'Customer service = atendimento ao cliente. Experience aqui é incontável.', false),
('ingles', 'cc2611-ingles-066', 'Inglês', null, 'Choose the best answer to "Why do you want to be a flight attendant?"', null, '[{"letra": "A", "texto": "Because the salary is good and the work is easy.", "imagem_url": null}, {"letra": "B", "texto": "I love working with people and I want a career focused on safety and service.", "imagem_url": null}, {"letra": "C", "texto": "Because I want to travel for free.", "imagem_url": null}, {"letra": "D", "texto": "I don''t know, my friend suggested it.", "imagem_url": null}]'::jsonb, 'B', 'Mostre motivação ligada à função: pessoas, segurança e serviço.', false),
('ingles', 'cc2611-ingles-067', 'Inglês', null, '"I''m a fast learner" means:', null, '[{"letra": "A", "texto": "Eu aprendo rápido.", "imagem_url": null}, {"letra": "B", "texto": "Eu trabalho rápido.", "imagem_url": null}, {"letra": "C", "texto": "Eu ensino rápido.", "imagem_url": null}, {"letra": "D", "texto": "Eu estudo à noite.", "imagem_url": null}]'::jsonb, 'A', 'Fast learner = alguém que aprende rápido.', false),
('ingles', 'cc2611-ingles-068', 'Inglês', null, 'How do you say the flight number "LA 8064" in the radio/aviation style?', null, '[{"letra": "A", "texto": "L A eight oh sixty-four", "imagem_url": null}, {"letra": "B", "texto": "L A eight thousand sixty-four", "imagem_url": null}, {"letra": "C", "texto": "L A eight zero six four", "imagem_url": null}, {"letra": "D", "texto": "L A eighty sixty-four", "imagem_url": null}]'::jsonb, 'C', 'Em aviação, os números são lidos dígito por dígito.', false),
('ingles', 'cc2611-ingles-069', 'Inglês', null, '"Quarter to five" is:', null, '[{"letra": "A", "texto": "4:15", "imagem_url": null}, {"letra": "B", "texto": "4:45", "imagem_url": null}, {"letra": "C", "texto": "5:45", "imagem_url": null}, {"letra": "D", "texto": "5:15", "imagem_url": null}]'::jsonb, 'B', 'Quarter to five = quinze para as cinco.', false),
('ingles', 'cc2611-ingles-070', 'Inglês', null, 'Seat "17C" is read as:', null, '[{"letra": "A", "texto": "seven teen sea", "imagem_url": null}, {"letra": "B", "texto": "seventy C", "imagem_url": null}, {"letra": "C", "texto": "one seven C", "imagem_url": null}, {"letra": "D", "texto": "seventeen C", "imagem_url": null}]'::jsonb, 'D', 'Assentos são lidos como número inteiro + letra: seventeen C.', false),
('ingles', 'cc2611-ingles-071', 'Inglês', null, 'What is "half past three"?', null, '[{"letra": "A", "texto": "3:15", "imagem_url": null}, {"letra": "B", "texto": "3:45", "imagem_url": null}, {"letra": "C", "texto": "2:30", "imagem_url": null}, {"letra": "D", "texto": "3:30", "imagem_url": null}]'::jsonb, 'D', 'Half past three = três e meia.', false),
('ingles', 'cc2611-ingles-072', 'Inglês', null, 'The temperature is 30 degrees Celsius. Which sentence is correct?', null, '[{"letra": "A", "texto": "It''s thirteen degrees Celsius.", "imagem_url": null}, {"letra": "B", "texto": "It''s thirty degrees Celsius.", "imagem_url": null}, {"letra": "C", "texto": "It makes thirty degrees.", "imagem_url": null}, {"letra": "D", "texto": "It has thirty degrees.", "imagem_url": null}]'::jsonb, 'B', 'Thirty = 30. Thirteen = 13. Usa-se It''s ... degrees.', false),
('ingles', 'cc2611-ingles-073', 'Inglês', null, '"Actually" means:', null, '[{"letra": "A", "texto": "na verdade", "imagem_url": null}, {"letra": "B", "texto": "atualmente", "imagem_url": null}, {"letra": "C", "texto": "realmente agora", "imagem_url": null}, {"letra": "D", "texto": "exatamente", "imagem_url": null}]'::jsonb, 'A', 'Falso cognato: actually = na verdade. Atualmente = currently.', false),
('ingles', 'cc2611-ingles-074', 'Inglês', null, '"Pretend" means:', null, '[{"letra": "A", "texto": "fingir", "imagem_url": null}, {"letra": "B", "texto": "pretender", "imagem_url": null}, {"letra": "C", "texto": "preparar", "imagem_url": null}, {"letra": "D", "texto": "prender", "imagem_url": null}]'::jsonb, 'A', 'Falso cognato: pretend = fingir. Pretender = intend.', false),
('ingles', 'cc2611-ingles-075', 'Inglês', null, '"Push" on a door means:', null, '[{"letra": "A", "texto": "pressione o botão", "imagem_url": null}, {"letra": "B", "texto": "empurre", "imagem_url": null}, {"letra": "C", "texto": "abra", "imagem_url": null}, {"letra": "D", "texto": "puxe", "imagem_url": null}]'::jsonb, 'B', 'Push = empurrar. Pull = puxar.', false),
('ingles', 'cc2611-ingles-076', 'Inglês', null, '"Exit" means:', null, '[{"letra": "A", "texto": "sucesso", "imagem_url": null}, {"letra": "B", "texto": "entrada", "imagem_url": null}, {"letra": "C", "texto": "saída", "imagem_url": null}, {"letra": "D", "texto": "êxito", "imagem_url": null}]'::jsonb, 'C', 'Exit = saída. Êxito = success.', false),
('ingles', 'cc2611-ingles-077', 'Inglês', null, '"Assist" in English usually means:', null, '[{"letra": "A", "texto": "assistir a um filme", "imagem_url": null}, {"letra": "B", "texto": "sentar", "imagem_url": null}, {"letra": "C", "texto": "ajudar", "imagem_url": null}, {"letra": "D", "texto": "observar", "imagem_url": null}]'::jsonb, 'C', 'Assist = ajudar. Assistir (TV) = watch.', false)
on conflict (banco, origem_id) do nothing;

select banco, categoria, count(*) as novas from questoes where origem_id like 'cc2611-%' group by 1, 2 order by 1, 2;
